<?php
declare(strict_types=1);
namespace Hls\Controllers;
use Hls\Http\HttpError; use Hls\Http\Input; use Hls\Http\View; use Hls\Repositories\Repository; use Hls\Middleware\Access; use Hls\Services\Audit; use Hls\Services\Csrf;
final class MaintenancePmController
{
 public function __construct(private Repository $repo,private View $view,private Access $access,private Audit $audit){}
 private function current(int $asset,string $basis):?float { $r=$this->repo->one('SELECT meter_reading,meter_type FROM eq_p2h_inspections WHERE asset_id=? AND status="REVIEWED" AND meter_reading IS NOT NULL ORDER BY inspected_at DESC,id DESC LIMIT 1',[$asset]); if(!$r||($basis==='HOUR_METER'&&$r['meter_type']!=='HM')||($basis==='KILOMETER'&&$r['meter_type']!=='KM'))return null; return (float)$r['meter_reading']; }
 private function scope(int $b):void{$this->access->demandBranch($b);}
 public function handle():void {
  $this->access->demand('maintenance.pm.view'); if($_SERVER['REQUEST_METHOD']==='POST')$this->post(); $id=Input::id($_GET,'id',true);$mode=Input::text($_GET,'mode',20,false);$detail=$id?$this->repo->one('SELECT s.*,b.name branch_name,a.code asset_code,a.name asset_name FROM maintenance_pm_schedules s JOIN branches b ON b.id=s.branch_id JOIN md_assets a ON a.id=s.asset_id WHERE s.id=?',[$id]):null;if($detail)$this->scope((int)$detail['branch_id']);$history=$id?$this->repo->all('SELECT h.*,w.wo_number FROM maintenance_pm_histories h JOIN maintenance_work_orders w ON w.id=h.work_order_id WHERE h.schedule_id=? ORDER BY h.performed_on DESC',[$id]):[];$rows=$this->repo->all('SELECT s.*,b.name branch_name,a.code asset_code,a.name asset_name FROM maintenance_pm_schedules s JOIN branches b ON b.id=s.branch_id JOIN md_assets a ON a.id=s.asset_id WHERE s.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY s.active DESC,s.id DESC',[$this->access->user['id'],$this->access->user['all_branches']]);$viewRows=[];$counts=['NORMAL'=>0,'UPCOMING'=>0,'DUE'=>0,'OVERDUE'=>0];$missing=0;foreach($rows as $r){$actual=$r['basis']==='CALENDAR'?null:$this->current((int)$r['asset_id'],$r['basis']);$remaining=null;if($r["basis"]==="CALENDAR"){if($r["next_due_date"]){$remaining=(int)((new \DateTimeImmutable("today"))->diff(new \DateTimeImmutable($r["next_due_date"]))->format("%r%a"));}}elseif($actual!==null&&$r["next_target"]!==null){$remaining=(float)$r["next_target"]-$actual;}$status=$remaining===null?'NORMAL':($remaining<0?'OVERDUE':($remaining<=($r['tolerance_value']?:0)?'DUE':($remaining<=($r['tolerance_value']*2?:1)?'UPCOMING':'NORMAL')));if($actual===null&&$r['basis']!=='CALENDAR')$missing++;$counts[$status]++;$r['actual_value']=$actual;$r['remaining_value']=$remaining;$r['due_status']=$status;$viewRows[]=$r;}$branches=$this->repo->all('SELECT id,name FROM branches WHERE active=1 ORDER BY name');$assets=$this->repo->all('SELECT id,code,name,branch_id FROM md_assets WHERE active=1 ORDER BY code');if($mode==='print'&&$detail){$this->access->demand('maintenance.pm.print');$this->view->render('maintenance-pm-print',compact('detail','history','viewRows'));return;} $this->view->render('maintenance-pm',compact('viewRows','counts','missing','branches','assets','id','detail','history')); }
 private function post():void { $action=Input::text($_POST,'action',20);$perm=$action==='create'?'maintenance.pm.create':($action==='wo'?'maintenance.wo.create':'maintenance.pm.manage');$this->access->demand($perm);Csrf::verify($_POST['csrf']??null);$this->repo->db->beginTransaction();try{$actor=(int)$this->access->user['id'];if($action==='create'){$b=Input::id($_POST,'branch_id');$a=Input::id($_POST,'asset_id');$this->scope($b);if(!$this->repo->one('SELECT id FROM md_assets WHERE id=? AND branch_id=? AND active=1',[$a,$b]))throw new HttpError(422,'Unit tidak sesuai cabang.');$basis=Input::text($_POST,'basis',20);$interval=(float)($_POST['interval_value']??0);if(!in_array($basis,['HOUR_METER','KILOMETER','CALENDAR'],true)||$interval<=0)throw new HttpError(422,'Basis atau interval tidak valid.');$code=Input::text($_POST,'schedule_code',80);$target=$basis==='CALENDAR'?null:(float)($_POST['next_target']??0);$date=$basis==='CALENDAR'?Input::text($_POST,'next_due_date',10,false):null;$policy=Input::text($_POST,'calculation_policy',20,false)?:'ACTUAL_BASED';if(!in_array($policy,['ACTUAL_BASED','FIXED_CYCLE'],true))throw new HttpError(422,'Kebijakan target tidak valid.');$this->repo->run('INSERT INTO maintenance_pm_schedules(schedule_code,schedule_name,branch_id,asset_id,service_type,basis,interval_value,initial_value,next_target,next_due_date,tolerance_value,calculation_policy,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$code,Input::text($_POST,'schedule_name',160),$b,$a,Input::text($_POST,'service_type',160),$basis,$interval,$target?:null,$target?:null,$date,(float)($_POST['tolerance_value']??0),$policy,Input::text($_POST,'notes',2000,false),$actor]);$id=(int)$this->repo->db->lastInsertId();$this->audit->record($actor,'maintenance_pm_created','maintenance_pm_schedules',$id,[]);}elseif($action==='wo'){$id=Input::id($_POST,'schedule_id');$s=$this->repo->one('SELECT * FROM maintenance_pm_schedules WHERE id=? FOR UPDATE',[$id]);if(!$s||!$s['active'])throw new HttpError(409,'Jadwal tidak aktif.');$this->scope((int)$s['branch_id']);$dup=$this->repo->one('SELECT id,wo_number FROM maintenance_work_orders WHERE pm_schedule_id=? AND status NOT IN("CLOSED","CANCELLED")',[$id]);if($dup)throw new HttpError(409,'Work Order aktif untuk siklus ini sudah ada.');$num='WO-PM-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$this->repo->run('INSERT INTO maintenance_work_orders(wo_number,branch_id,asset_id,pm_schedule_id,created_by,work_type,priority,status,problem_description,target_date) VALUES(?,?,?,?,?,"PREVENTIVE","NORMAL","DRAFT",?,?)',[$num,$s['branch_id'],$s['asset_id'],$id,$actor,'Preventive: '.$s['service_type'],$s['basis']==='CALENDAR'?$s['next_due_date']:null]);$wo=(int)$this->repo->db->lastInsertId();$this->audit->record($actor,'maintenance_pm_wo_created','maintenance_pm_schedules',$id,['work_order_id'=>$wo]);}$this->repo->db->commit();$this->view->redirect('/maintenance/preventive');}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}}
}
